function candidate(person,job){const shared=job.skills.filter(s=>person.skills.includes(s)),missing=job.skills.filter(s=>!person.skills.includes(s)),trainable=missing.every(s=>job.trainable[s]);return {person,job,shared,missing,eligible:shared.length>=3&&trainable,weeks:missing.reduce((n,s)=>n+(job.trainable[s]?.weeks||0),0),training:missing.reduce((n,s)=>n+(job.trainable[s]?.cost||0),0)};}
const COMPETITION_TEAM=[TEAM[0],TEAM[1],{id:'riley',department:'Customer Operations',name:'Riley Chen',initials:'RC',role:'Technical Support Analyst',salary:50000,skills:['Troubleshooting','Ticketing','Documentation','AI answer verification'],note:'Fictional competition example: all four listed IT support skills are present.'}];
function scenarioScope({department='all',closing=false,competition=false}={}){const team=competition?COMPETITION_TEAM:TEAM,jobs=competition?[JOBS[0]]:JOBS;return {people:team.filter(p=>department==='all'||p.department===department),vacancies:jobs.filter(j=>!closing||department==='all'||j.department!==department)};}
function compareFit(a,b){return b.shared.length-a.shared.length||a.weeks-b.weeks||a.training-b.training||a.person.name.localeCompare(b.person.name);}
function findMatches({weeks,budget,department='all',closing=false,competition=false}){const {people,vacancies}=scenarioScope({department,closing,competition});let best={moves:[],training:0,overlap:0,learningWeeks:0,key:''};function visit(index,used,moves,training,overlap,learningWeeks){if(index===people.length){const key=moves.map(m=>m.person.name+':'+m.job.id).sort().join('|');const better=moves.length>best.moves.length||(moves.length===best.moves.length&&(overlap>best.overlap||(overlap===best.overlap&&(learningWeeks<best.learningWeeks||(learningWeeks===best.learningWeeks&&(training<best.training||(training===best.training&&key<best.key)))))));if(better)best={moves:[...moves],training,overlap,learningWeeks,key};return;}for(const job of vacancies){if(used.has(job.id))continue;const c=candidate(people[index],job);if(!c.eligible||c.weeks>weeks||training+c.training>budget)continue;used.add(job.id);moves.push(c);visit(index+1,used,moves,training+c.training,overlap+c.shared.length,learningWeeks+c.weeks);moves.pop();used.delete(job.id);}visit(index+1,used,moves,training,overlap,learningWeeks);}visit(0,new Set(),[],0,0,0);return {...best,people,vacancies,department,closing,competition};}
function vacancyCandidates(result,job){return result.people.map(p=>candidate(p,job)).sort(compareFit);}
function costComparison(result,assumptions){const {hire,severance,onboard,admin}=assumptions;const people=result.people||TEAM,vacancies=result.vacancies||JOBS;const severanceFor=p=>p.salary/52*severance;const allSeverance=people.reduce((n,p)=>n+severanceFor(p),0),filled=new Set(result.moves.map(m=>m.person.id)),remainingSeverance=people.filter(p=>!filled.has(p.id)).reduce((n,p)=>n+severanceFor(p),0),baselineHiring=vacancies.length*(hire+onboard),alternativeHiring=(vacancies.length-result.moves.length)*(hire+onboard),transferAdmin=result.moves.length*admin,baseline=allSeverance+baselineHiring,alternative=remainingSeverance+alternativeHiring+result.training+transferAdmin;return {baseline,alternative,saving:baseline-alternative,allSeverance,remainingSeverance,baselineHiring,alternativeHiring,training:result.training,transferAdmin};}
function departmentBreakdown(result){const rows=[...new Set(result.vacancies.map(j=>j.department))].map(department=>({department,moves:result.moves.filter(m=>m.job.department===department),openings:result.vacancies.filter(j=>j.department===department).length}));return {rows,unmatched:result.people.filter(p=>!result.moves.some(m=>m.person.id===p.id)),total:result.people.length};}

