function careerPossibilities(person,{department='all',closing=false}={}){return ROLE_LIBRARY.filter(role=>role.availability!=='current'&&(!closing||department==='all'||role.department!==department)).map(role=>candidate(person,role)).filter(c=>c.shared.length>=2&&c.missing.every(s=>c.job.trainable[s])).sort((a,b)=>b.shared.length-a.shared.length||a.weeks-b.weeks||a.job.title.localeCompare(b.job.title)).slice(0,3);}

